set -e
T=$(mktemp -d /tmp/bot-test-XXXX)
cat > "$T/test.mjs" <<'EOF'
import assert from 'node:assert/strict';
import { readdirSync, appendFileSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
const BOT = process.env.BOT;
const { recordUnsubscribe, recordResubscribe, mayEmail } = await import(BOT);
const M = 'marketing', X = 'transactional';
const t = (s) => new Date(s);
const now = t('2026-10-22T12:00:00Z');
const mk = (to, kind) => mayEmail({ to, kind }, now);

// 1. fresh address, marketing allowed
assert.deepEqual(await mk('ann@example.com', M), { allowed: true, reason: null });

// 2. unsubscribe blocks marketing, not transactional
await recordUnsubscribe('ann@example.com', t('2026-10-01T10:00:00Z'));
assert.deepEqual(await mk('ann@example.com', M), { allowed: false, reason: 'unsubscribed' });
assert.deepEqual(await mk('ann@example.com', X), { allowed: true, reason: null });

// 3. aliases of the same person: case, header wrapping, plus tag, gmail dots/googlemail
await recordUnsubscribe('"Doe, Jane" <<EMAIL>>', t('2026-10-01T10:00:00Z'));
assert.equal((await mk('<EMAIL>', M)).reason, 'unsubscribed');
assert.equal((await mk('<EMAIL>', M)).reason, 'unsubscribed');
assert.equal((await mk('  <EMAIL> ', M)).reason, 'unsubscribed');
assert.equal((await mk('<EMAIL>', X)).allowed, true);
// dots are not ignored outside gmail
await recordUnsubscribe('a.b@example.com', t('2026-10-01T10:00:00Z'));
assert.equal((await mk('ab@example.com', M)).allowed, true);

// 4. resubscribe after unsubscribe re-enables marketing
await recordResubscribe('ann@example.com', t('2026-10-05T10:00:00Z'));
assert.equal((await mk('ann@example.com', M)).allowed, true);

// 5. out-of-order: resubscribe (Oct 5) delivered before the older unsubscribe (Oct 3) -> still subscribed
await recordUnsubscribe('bob@example.com', t('2026-10-03T10:00:00Z'));
assert.equal((await mk('bob@example.com', M)).reason, 'unsubscribed');
await recordResubscribe('bob@example.com', t('2026-10-05T10:00:00Z'));
assert.equal((await mk('bob@example.com', M)).allowed, true);
// a late-arriving unsubscribe that is older than the resubscribe must not reverse it
await recordUnsubscribe('bob@example.com', t('2026-10-04T10:00:00Z'));
assert.equal((await mk('bob@example.com', M)).allowed, true);
// a newer unsubscribe does reverse it
await recordUnsubscribe('bob@example.com', t('2026-10-06T10:00:00Z'));
assert.equal((await mk('bob@example.com', M)).reason, 'unsubscribed');

// 6. exact timestamp tie: unsubscribe wins regardless of arrival order
const ts = t('2026-10-07T10:00:00Z');
await recordResubscribe('tie@example.com', ts);
await recordUnsubscribe('tie@example.com', ts);
assert.equal((await mk('tie@example.com', M)).reason, 'unsubscribed');
await recordUnsubscribe('tie2@example.com', ts);
await recordResubscribe('tie2@example.com', ts);
assert.equal((await mk('tie2@example.com', M)).reason, 'unsubscribed');

// 7. invalid input
assert.deepEqual(await mk('not-an-address', M), { allowed: false, reason: 'invalid_recipient' });
assert.deepEqual(await mk('x@localhost', M), { allowed: false, reason: 'invalid_recipient' });
assert.deepEqual(await mk('ok@example.com', 'newsletter'), { allowed: false, reason: 'unknown_kind' });
await assert.rejects(recordUnsubscribe('ann@example.com', 'yesterday'), TypeError);
await assert.rejects(mayEmail({ to: 'ann@example.com', kind: M }, 'now'), TypeError);

// 8. a torn trailing line from a crashed worker does not hide real events
const dir = path.join(process.env.STATE_DIR, 'suppression');
const file = readdirSync(dir).map(f => path.join(dir, f)).find(f => readFileSync(f, 'utf8').includes('"address":"ann@example.com"'));
appendFileSync(file, '\n{"type":"unsub');
await recordUnsubscribe('ann@example.com', t('2026-10-20T10:00:00Z'));
assert.equal((await mk('ann@example.com', M)).reason, 'unsubscribed');

// 9. the state file is written with fsync'd appends; a restarted process (fresh module) sees it
const fresh = await import(BOT + '?restart=1');
assert.equal((await fresh.mayEmail({ to: 'ann@example.com', kind: M }, now)).reason, 'unsubscribed');

// 10. no STATE_DIR -> throws, does not silently write elsewhere
const saved = process.env.STATE_DIR; delete process.env.STATE_DIR;
await assert.rejects(recordUnsubscribe('z@example.com', t('2026-10-01T10:00:00Z')), /STATE_DIR/);
process.env.STATE_DIR = saved;

// 11. concurrent workers: 8 processes x 60 events against shared STATE_DIR
const run = promisify(execFile);
const worker = `
const { recordUnsubscribe, recordResubscribe } = await import(process.env.BOT);
const id = process.argv[1];
for (let i = 0; i < 60; i++) {
  const at = new Date(Date.UTC(2026, 9, 1) + i * 1000);
  const addr = 'load' + (i % 5) + '@example.com';
  await (i % 2 ? recordUnsubscribe : recordResubscribe)(addr, at);
}`;
const wpath = path.join(path.dirname(BOT.replace('file://','')), '..', 'w.mjs');
const { writeFileSync } = await import('node:fs');
writeFileSync('/tmp/bot-worker-' + process.pid + '.mjs', worker);
await Promise.all([...Array(8).keys()].map(i => run(process.execPath, ['/tmp/bot-worker-' + process.pid + '.mjs', String(i)], { env: { ...process.env, BOT } })));
let lines = 0;
for (const f of readdirSync(dir)) {
  const text = readFileSync(path.join(dir, f), 'utf8');
  lines += text.split('\n').filter(l => l.startsWith('{')).length;
}
// 8*60 = 480 concurrent events, plus the events written by the earlier steps (counted separately below)
assert.ok(lines >= 480, `expected >= 480 events, got ${lines}`);
// each concurrent event must be parseable
for (let i = 0; i < 5; i++) {
  const { readdirSync: _r } = await import('node:fs');
}
console.log('lines written (all steps):', lines);
// last-writer-by-time on load0: i%2==1 -> unsub. i%5==0 -> i in {0,5,...,55}. Last one with i%5==0 & i= 55: 55%2=1 -> unsub at 55s.
assert.equal((await mk('load0@example.com', M)).reason, 'unsubscribed');
// load2: i%5==2 -> i=57 is last, 57 odd -> unsub. load1: i=56 even -> resub, last by time i=56 -> subscribed
assert.equal((await mk('load1@example.com', M)).allowed, true);
console.log('ALL CHECKS PASSED');
EOF
cd "$T" && STATE_DIR="$T/state" BOT="file://<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g3-1/bot.mjs" node test.mjs; echo "exit=$?"; echo "TMP=$T"
